"""A minimal ECS with a frame-local event bus and deferred structural changes.

Key invariants:
  - Events emitted during a frame are visible to systems that run later
    *within the same frame* (FIFO ordering).
  - Structural changes (entity destruction) are queued and only flushed
    after ALL systems have run, so an entity killed this frame is still
    fully visible to every system this frame.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Callable, Type


# --------------------------------------------------------------------------
# Events
# --------------------------------------------------------------------------

@dataclass
class DamageEvent:
    target: int
    amount: int
    source: int | None = None


@dataclass
class DeathEvent:
    entity: int
    killer: int | None = None


class EventBus:
    """Frame-local event bus. Cleared at the start of each frame."""

    def __init__(self) -> None:
        self._events: list[tuple[Type, object]] = []
        self._handlers: dict[Type, list[Callable]] = {}

    def emit(self, event: object) -> None:
        self._events.append((type(event), event))

    def subscribe(self, event_type: Type, handler: Callable) -> None:
        self._handlers.setdefault(event_type, []).append(handler)

    def events_of(self, event_type: Type) -> list:
        """Events of this type so far this frame, oldest first (FIFO)."""
        return [e for t, e in self._events if t is event_type]

    @property
    def all_events(self) -> list:
        return [e for _, e in self._events]

    def new_frame(self) -> None:
        self._events.clear()


# --------------------------------------------------------------------------
# World with deferred destruction
# --------------------------------------------------------------------------

class World:
    def __init__(self) -> None:
        self.bus = EventBus()
        self.next_id: int = 1
        self.entities: dict[int, dict] = {}      # id -> component dict
        self.pending_destroy: set[int] = set()   # queued destroys
        self.systems: list[Callable[[World], None]] = []

    # -- entity management ------------------------------------------------

    def spawn(self, **components) -> int:
        eid = self.next_id
        self.next_id += 1
        self.entities[eid] = components
        return eid

    def destroy(self, eid: int) -> None:
        """Queue destruction; applied only on flush after all systems run."""
        self.pending_destroy.add(eid)

    def flush(self) -> None:
        for eid in self.pending_destroy:
            self.entities.pop(eid, None)
        self.pending_destroy.clear()

    def alive(self, eid: int) -> bool:
        return eid in self.entities

    # -- systems / frame loop ----------------------------------------------

    def add_system(self, system: Callable[["World"], None]) -> None:
        self.systems.append(system)

    def run_frame(self) -> None:
        self.bus.new_frame()
        for system in self.systems:
            system(self)
        self.flush()


# --------------------------------------------------------------------------
# Built-in demo systems used by tests
# --------------------------------------------------------------------------

def damage_system(world: World) -> None:
    """Applies pending DamageEvents; emits DeathEvent when hp <= 0."""
    hp_map = world.entities.get(0, {"hp": {}}).get("hp")  # not used; see below
    del hp_map

    hp_store: dict[int, int] = {}
    for eid, comps in world.entities.items():
        if "hp" in comps:
            hp_store[eid] = comps["hp"]

    deaths: list[DeathEvent] = []
    for ev in world.bus.events_of(DamageEvent):
        if not world.alive(ev.target):
            continue  # already queued for destruction this frame
        if eid_queued(ev.target, world):
            continue
        new_hp = hp_store.get(ev.target, 0) - ev.amount
        if "hp" in world.entities.get(ev.target, {}):
            world.entities[ev.target]["hp"] = new_hp
            hp_store[ev.target] = new_hp
        if new_hp <= 0:
            deaths.append(DeathEvent(entity=ev.target, killer=ev.source))

    for d in deaths:
        world.destroy(d.entity)
        world.bus.emit(d)


def eid_queued(eid: int, world: World) -> bool:
    return eid in world.pending_destroy


def cleanup_system(world: World) -> None:
    """Destroys entities that received a DeathEvent (destroy is deferred)."""
    for death in world.bus.events_of(DeathEvent):
        world.destroy(death.entity)


def lifetime_log_system(world: World) -> None:
    """Records which known entities are still visible each frame."""
    log: list = world.entities.setdefault("__log__", []) if False else getattr(world, "visibility_log", None)
    if log is None:
        log = []
        world.visibility_log = log
    log.append({eid for eid in world.entities if isinstance(eid, int)})


def mutual_kill_system(world: World) -> None:
    """Two fighters kill each other simultaneously when both are low."""
    fighters = [
        (eid, c["hp"]) for eid, c in world.entities.items()
        if isinstance(eid, int) and c.get("tag") == "fighter" and c.get("hp", 99) <= 5
    ]
    if len(fighters) == 2:
        (a, _), (b, _) = fighters
        world.bus.emit(DamageEvent(target=a, amount=10, source=b))
        world.bus.emit(DamageEvent(target=b, amount=10, source=a))

